window.kbPageData["views/entry/k-c133b1ea9487e877"] = {"key":"entry/k-c133b1ea9487e877","state":{"route":"entry/k-c133b1ea9487e877"},"node":{"id":"k-c133b1ea9487e877","mode":"k","title":"消费欺诈的惩罚性赔偿","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["经营者欺诈时消费者有权请求价款或服务费用三倍且最低五百元的增加赔偿"],"qs":["江苏 2025 A类 行测#17"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"经营者提供商品或者服务有欺诈行为的，消费者有权要求增加赔偿。增加赔偿额为商品价款或者服务费用的三倍，不足五百元的按五百元计算，法律另有规定的依其规定。","review":{"definition":"经营者提供商品或者服务有欺诈行为的，消费者有权要求增加赔偿。增加赔偿额为商品价款或者服务费用的三倍，不足五百元的按五百元计算，法律另有规定的依其规定。","explanation":"第17题中，M公司以门锁具备“生成临时密码”功能招徕购买，却在韩某购买安装后才告知该功能需付费升级。按题意，这一行为构成消费欺诈，韩某可以要求增加赔偿，故C项成立。本题未给出门锁价款，判断的是赔偿请求权。","references":[],"evidence":"增加赔偿的金额不足五百元的，为五百元","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 A类 行测#17":{"paper":"江苏 2025 A类 行测","n":17,"mod":"常识判断","src":["98687766ac277f427cd6.pdf",4],"asrc":["4fe8e0544dd7b47699d2.pdf",7],"card":"43df3c0b89b8393bd389e5be","links":[{"id":"k-c133b1ea9487e877","role":"直接考查","why":"经营者欺诈触发消费者请求法定增加赔偿的权利。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-c133b1ea9487e877":[["江苏 2025 A类 行测#17"]]}};
